import{_ as e,C as o,o as s,c as n,j as d,a as r,E as h,a2 as i}from"./chunks/framework.wVcpyw2-.js";const l="/images/placeholder-user-region-config-admin.svg",k=JSON.parse('{"title":"系统配置总览","description":"灵萌管理后台系统配置 12 个 Tab 说明：微信、支付、存储、地图、短信、区域与上传等全站级配置入口与建议顺序。","frontmatter":{"title":"系统配置总览","description":"灵萌管理后台系统配置 12 个 Tab 说明：微信、支付、存储、地图、短信、区域与上传等全站级配置入口与建议顺序。"},"headers":[],"relativePath":"config/system-settings.md","filePath":"config/system-settings.md","lastUpdated":1785535852000}'),b={name:"config/system-settings.md"};function p(g,t,c,u,m,f){const a=o("SystemSettingsOverview");return s(),n("div",null,[t[0]||(t[0]=d("h1",{id:"系统配置总览",tabindex:"-1"},[r("系统配置总览 "),d("a",{class:"header-anchor",href:"#系统配置总览","aria-label":'Permalink to "系统配置总览"'},"​")],-1)),t[1]||(t[1]=d("p",null,[d("strong",null,"系统设置 → 系统配置"),r(" 是灵萌全站级配置的集中入口。下方卡片可快速定位各 Tab；保存后多数项立即生效，带测试按钮的项须点通后再用于生产。")],-1)),h(a),t[2]||(t[2]=i('<hr><h2 id="配置详情" tabindex="-1">配置详情 <a class="header-anchor" href="#配置详情" aria-label="Permalink to &quot;配置详情&quot;">​</a></h2><p><img src="'+l+'" alt="系统配置示意"></p><h2 id="tab-wechat-mini" tabindex="-1">Tab 1：微信小程序 <a class="header-anchor" href="#tab-wechat-mini" aria-label="Permalink to &quot;Tab 1：微信小程序 {#tab-wechat-mini}&quot;">​</a></h2><p><strong>作用：</strong> 小程序登录、小程序支付、订阅消息、获取手机号等。</p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>在哪里找</th><th>说明</th></tr></thead><tbody><tr><td>小程序 AppID</td><td>用小程序时必填</td><td><a href="https://mp.weixin.qq.com" target="_blank" rel="noreferrer">微信公众平台</a> → <strong>开发</strong> → <strong>开发管理</strong> → <strong>开发设置</strong></td><td>形如 <code>wx</code> 开头，勿与公众号 AppID 混用</td></tr><tr><td>小程序密钥 AppSecret</td><td>必填</td><td>同上，需管理员扫码后重置/查看</td><td>泄露后立即在微信后台重置</td></tr><tr><td>原始 ID</td><td>可选</td><td>公众平台 → <strong>设置</strong> → <strong>账号信息</strong></td><td>以 <code>gh_</code> 开头，不是 AppID</td></tr><tr><td>Access Token</td><td>只读</td><td>系统自动刷新</td><td>无需手填</td></tr><tr><td><strong>立即获取 Token</strong></td><td>—</td><td>填完 AppID/Secret 后点击</td><td>成功=连通；失败检查 Secret 与服务器出网</td></tr></tbody></table><p><strong>操作步骤：</strong></p><ol><li>登录微信公众平台 → 复制 AppID、AppSecret</li><li>管理后台 <strong>系统设置 → 系统配置 → 微信小程序</strong> Tab 粘贴</li><li>点击 <strong>立即获取 Token</strong>，提示成功</li><li>到 <strong>区域管理 → 用户配置</strong> 开启「允许微信小程序登录」</li><li>小程序后台 <strong>开发管理 → 开发设置 → 服务器域名</strong> 添加你的 API 域名</li></ol><p><strong>常见错误：</strong></p><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>Token 失败</td><td>Secret 多空格；用了公众号 Secret；服务器无法访问 <code>api.weixin.qq.com</code></td></tr><tr><td>小程序能打开但不能登录</td><td>区域 <strong>用户配置</strong> 未开微信登录；AppID 与打包小程序不一致</td></tr><tr><td>订阅消息发不出</td><td>需在 <strong>通知控制台 → 微信模板</strong> 单独配置模板 ID</td></tr></tbody></table><p>→ 详见 <a href="/features/wechat">微信功能开启</a></p><hr><h2 id="tab-wechat-mp" tabindex="-1">Tab 2：微信公众号 <a class="header-anchor" href="#tab-wechat-mp" aria-label="Permalink to &quot;Tab 2：微信公众号 {#tab-wechat-mp}&quot;">​</a></h2><p><strong>作用：</strong> H5 网页微信登录、公众号模板消息。</p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>在哪里找</th></tr></thead><tbody><tr><td>公众号 AppID</td><td>H5 微信登录必填</td><td>公众平台 → 开发设置（与服务号/订阅号对应）</td></tr><tr><td>公众号密钥</td><td>必填</td><td>同上</td></tr><tr><td>公众号原始 ID</td><td>可选</td><td>账号信息页 <code>gh_</code></td></tr><tr><td><strong>立即获取 Token</strong></td><td>—</td><td>同小程序</td></tr></tbody></table><p><strong>额外必须在微信后台配置：</strong></p><ol><li><strong>设置与开发 → 公众号设置 → 功能设置 → 网页授权域名</strong><br> 填你的站点域名（不含 <code>https://</code>），须与 <strong>网站信息</strong>、初始化向导中的 <strong>网站地址</strong> 一致</li><li>若用模板消息：<strong>广告与服务 → 模板消息</strong> 申请模板</li></ol><hr><h2 id="tab-wechat-pay" tabindex="-1">Tab 3：微信支付 <a class="header-anchor" href="#tab-wechat-pay" aria-label="Permalink to &quot;Tab 3：微信支付 {#tab-wechat-pay}&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">需 payment 模块已开通</p></div><p><strong>作用：</strong> 用户支付、红包、转账、提现自动打款。</p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>在哪里找</th><th>说明</th></tr></thead><tbody><tr><td>商户号</td><td>必填</td><td><a href="https://pay.weixin.qq.com" target="_blank" rel="noreferrer">微信商户平台</a></td><td>10 位数字</td></tr><tr><td>支付密钥</td><td>必填</td><td>商户平台 → <strong>账户中心 → API 安全</strong></td><td>注意 v2/v3 版本，按页面提示填</td></tr><tr><td>v3 证书序列号</td><td>v3 必填</td><td>API 证书管理</td><td>证书过期需更新</td></tr><tr><td>支付公钥 ID</td><td>部分场景</td><td>商户平台</td><td>验签用</td></tr><tr><td>转账场景 ID</td><td>自动打款需要</td><td><strong>产品中心 → 商家转账</strong> 申请场景</td><td>未申请勿开自动提现</td></tr><tr><td>CERT 证书</td><td>退款/转账等</td><td>下载 <code>apiclient_cert.pem</code></td><td>完整 PEM，含头尾行</td></tr><tr><td>KEY 私钥</td><td>同上</td><td>下载 <code>apiclient_key.pem</code></td><td>勿与公钥搞反</td></tr><tr><td>支付公钥</td><td>v3 验签</td><td>商户平台下载</td><td>—</td></tr></tbody></table><p><strong>商户平台必配回调 URL：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://你的域名/api/payment/wx-notify</span></span></code></pre></div><p>路径：<strong>产品中心 → 开发配置 → 支付配置 → Native/JSAPI 等 → 通知 URL</strong></p><p><strong>操作 checklist：</strong></p><ul><li>[ ] 商户号与小程序 AppID 已在商户平台 <strong>AppID 账号管理</strong> 中绑定</li><li>[ ] 回调 URL 已填且为 <strong>HTTPS</strong></li><li>[ ] 证书与密钥已粘贴保存</li><li>[ ] 发起 0.01 元测试单，<strong>财务管理 → 资金交易</strong> 有记录</li></ul><p>→ 详见 <a href="/features/payment">支付与提现</a></p><hr><h2 id="tab-alipay" tabindex="-1">Tab 4：支付宝 <a class="header-anchor" href="#tab-alipay" aria-label="Permalink to &quot;Tab 4：支付宝 {#tab-alipay}&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">需 payment 模块已开通</p></div><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>App ID</td><td>必填</td><td><a href="https://open.alipay.com" target="_blank" rel="noreferrer">支付宝开放平台</a> 应用 ID</td></tr><tr><td>生产环境</td><td>上线必开</td><td>关=沙箱，开=生产；密钥与环境必须匹配</td></tr><tr><td>应用私钥</td><td>必填</td><td>RSA2 私钥，<strong>不是</strong>应用公钥</td></tr><tr><td>支付宝公钥</td><td>必填</td><td>开放平台提供的 <strong>支付宝公钥</strong>，不是你自己生成的应用公钥</td></tr></tbody></table><p><strong>回调 URL：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://你的域名/api/payment/alipay-notify</span></span></code></pre></div><p>在开放平台应用 → <strong>开发设置 → 接口加签方式</strong> 配置。</p><hr><h2 id="tab-storage" tabindex="-1">Tab 5：文件存储 <a class="header-anchor" href="#tab-storage" aria-label="Permalink to &quot;Tab 5：文件存储 {#tab-storage}&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">需 cloud_storage 模块已开通</p></div><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>存储方式</td><td><strong>本地</strong> / 腾讯云 COS / 阿里云 OSS / 七牛云</td></tr><tr><td>云存储时本地备份</td><td>建议开启，云+本地双份更安全</td></tr></tbody></table><h3 id="选「本地」" tabindex="-1">选「本地」 <a class="header-anchor" href="#选「本地」" aria-label="Permalink to &quot;选「本地」&quot;">​</a></h3><ul><li>文件存在服务器磁盘，适合小规模、内网</li><li>需保证 <code>uploads</code> 目录可写，且 <strong>Nginx 能访问静态文件</strong> 或通过 API 代理</li></ul><h3 id="选「腾讯云-cos」" tabindex="-1">选「腾讯云 COS」 <a class="header-anchor" href="#选「腾讯云-cos」" aria-label="Permalink to &quot;选「腾讯云 COS」&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>来源</th></tr></thead><tbody><tr><td>SecretId / SecretKey</td><td><a href="https://console.cloud.tencent.com/cam/capi" target="_blank" rel="noreferrer">腾讯云 CAM</a></td></tr><tr><td>Bucket</td><td>形如 <code>name-1250000000</code></td></tr><tr><td>Region</td><td>如 <code>ap-guangzhou</code>，须与 Bucket 一致</td></tr><tr><td>访问域名</td><td>CDN 或 COS 默认域名，<strong>必须公网 HTTPS 可访问</strong></td></tr></tbody></table><h3 id="选「阿里云-oss」" tabindex="-1">选「阿里云 OSS」 <a class="header-anchor" href="#选「阿里云-oss」" aria-label="Permalink to &quot;选「阿里云 OSS」&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>来源</th></tr></thead><tbody><tr><td>AccessKeyId / AccessKeySecret</td><td>RAM 控制台</td></tr><tr><td>Bucket / Endpoint</td><td>OSS 控制台（注意内网/外网 Endpoint）</td></tr><tr><td>访问域名</td><td>绑定 CDN 域名</td></tr></tbody></table><h3 id="选「七牛云」" tabindex="-1">选「七牛云」 <a class="header-anchor" href="#选「七牛云」" aria-label="Permalink to &quot;选「七牛云」&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>来源</th></tr></thead><tbody><tr><td>AccessKey / SecretKey</td><td>七牛控制台</td></tr><tr><td>Bucket / 访问域名</td><td>须 HTTPS 绑定</td></tr><tr><td>存储区域</td><td>与 Bucket 区域一致（华东/华北/华南等）</td></tr></tbody></table><p><strong>保存前点击「连接测试」</strong>，上传测试文件成功后再用于生产。</p><p>→ 详见 <a href="/features/storage">文件存储</a></p><hr><h2 id="tab-sms" tabindex="-1">Tab 6：腾讯云短信 <a class="header-anchor" href="#tab-sms" aria-label="Permalink to &quot;Tab 6：腾讯云短信 {#tab-sms}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>来源</th></tr></thead><tbody><tr><td>SdkAppId</td><td>必填</td><td><a href="https://console.cloud.tencent.com/smsv2" target="_blank" rel="noreferrer">短信控制台</a></td></tr><tr><td>短信签名</td><td>必填</td><td>控制台 → 签名管理（须审核通过）</td></tr><tr><td>模板 ID</td><td>必填</td><td>正文模板（验证码类）</td></tr><tr><td>测试手机号</td><td>测试用</td><td>11 位手机号，点 <strong>发送测试</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>短信测试用的 SecretId/Key 若此处留空，会 <strong>复用文件存储 Tab 里腾讯云 COS 的密钥</strong>。</p></div><p>到 <strong>区域管理 → 用户配置</strong> 开启「注册/登录验证码」后才会实际发送。</p><p>→ 详见 <a href="/features/sms">短信验证码</a></p><hr><h2 id="tab-amap" tabindex="-1">Tab 7：高德地图 <a class="header-anchor" href="#tab-amap" aria-label="Permalink to &quot;Tab 7：高德地图 {#tab-amap}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Key (原生)</td><td>后端必填</td><td><strong>Web 服务</strong></td><td>POI 搜索、距离计算等后端接口</td></tr><tr><td>WebKey (JS API)</td><td>前端必填</td><td><strong>Web端(JS API)</strong></td><td>H5/小程序地图组件</td></tr><tr><td>安全密钥</td><td>JS API 必填</td><td>jscode</td><td>2021 年后前端必配，否则地图报错</td></tr></tbody></table><p>申请地址：<a href="https://console.amap.com/dev/key/app" target="_blank" rel="noreferrer">高德控制台</a></p><p><strong>注意：</strong> Web 服务 Key 和 JS API Key <strong>不是同一个</strong>，各填各的输入框。</p><p>→ 详见 <a href="/features/map">地图与定位</a></p><hr><h2 id="tab-aliyun" tabindex="-1">Tab 8：阿里云 <a class="header-anchor" href="#tab-aliyun" aria-label="Permalink to &quot;Tab 8：阿里云 {#tab-aliyun}&quot;">​</a></h2><p>主要用于 <strong>IP 归属地</strong>（距离限制）、快递查询、地址解析等。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>IP 归属地接口</td><td>四选一，见下表</td></tr><tr><td>AppCode</td><td>阿里云市场 AppCode（lundear/kzipquery 查 IP 必填；选高德 IP 或 ip2region 时可不填，但快递等仍可能需要）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>选项</th><th>配置值</th><th>适用场景</th></tr></thead><tbody><tr><td>IP/IPv6 归属地查询</td><td><code>lundear</code></td><td>有 CDN、需 IPv6</td></tr><tr><td>高精准全球 IP</td><td><code>kzipquery</code></td><td>纯 IPv4、无 CDN</td></tr><tr><td>高德高级 IP</td><td><code>amap</code></td><td>已有高德 Web 服务 Key</td></tr><tr><td>ip2region 离线库</td><td><code>ip2region</code></td><td>本地 xdb，无需 AppCode；见 <a href="/features/map#server-config">地图与定位</a></td></tr></tbody></table><p>页面内 <strong>前往开通</strong> 链接可跳到对应商品页。</p><hr><h2 id="tab-region" tabindex="-1">Tab 9：区域配置 <a class="header-anchor" href="#tab-region" aria-label="Permalink to &quot;Tab 9：区域配置 {#tab-region}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>区域模式</td><td><strong>平台模式</strong>（全站单区）/ <strong>多区域自选</strong> / <strong>固定区域</strong></td></tr><tr><td>固定区域</td><td>选「固定区域」时，点 <strong>选择</strong> 指定区域 ID，不能填 0</td></tr><tr><td>首次须选区域</td><td>仅 <strong>多区域自选</strong>：开启时用户须先进入区域选择页；关闭时可直接进入平台页</td></tr><tr><td>隐藏平台入口</td><td>仅 <strong>多区域自选</strong>：开启后区域选择页不展示「平台」选项</td></tr><tr><td>距离限制（米）</td><td>用户与区域中心最大距离，默认 1000；依赖 IP 归属地或定位</td></tr></tbody></table><table tabindex="0"><thead><tr><th>模式</th><th>用户侧表现</th></tr></thead><tbody><tr><td>平台模式</td><td>所有人不绑定区域，无需选择</td></tr><tr><td>多区域自选</td><td>可配置是否必须先选区域、是否展示平台入口</td></tr><tr><td>固定区域</td><td>新用户自动绑定指定区域</td></tr></tbody></table><p>与 <a href="/config/region">区域管理</a> 配合：此处定 <strong>规则</strong>，区域列表定 <strong>有哪些区域</strong>。</p><hr><h2 id="tab-features" tabindex="-1">Tab 10：功能与上传 <a class="header-anchor" href="#tab-features" aria-label="Permalink to &quot;Tab 10：功能与上传 {#tab-features}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>建议</th></tr></thead><tbody><tr><td>显示公众号绑定</td><td>前端是否展示「关注公众号」入口</td><td>需同时上传二维码</td></tr><tr><td>新用户信息模式</td><td><strong>空白</strong> 或 <strong>随机头像昵称</strong></td><td>空白=用户自己填；随机=减少冷启动空白感</td></tr><tr><td>公众号二维码</td><td>引导关注的图片</td><td>从媒体库上传</td></tr><tr><td>禁止的后缀</td><td>上传黑名单，逗号分隔 <strong>不含点</strong></td><td>如 <code>exe,bat</code>；留空=内置默认黑名单</td></tr><tr><td>最大文件大小（MB）</td><td>单文件上限，默认 20</td><td>须 ≤ Nginx <code>client_max_body_size</code> 与后端限制</td></tr></tbody></table><p>区域级上传规则可在 <strong>区域管理 → 笔记配置</strong> 等页面覆盖。</p><hr><h2 id="tab-watermark" tabindex="-1">Tab 11：视频水印 <a class="header-anchor" href="#tab-watermark" aria-label="Permalink to &quot;Tab 11：视频水印 {#tab-watermark}&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">需 watermark 模块已开通；视频封面与整段视频水印依赖服务器 <strong>ffmpeg + ffprobe</strong> 均在 PATH 中可执行（见页内「服务端媒体依赖」检测）。宝塔软件商店 FFmpeg 插件常缺 ffprobe，建议用终端 <code>apt/yum/dnf install ffmpeg</code> 安装完整包，见 <a href="/guide/quick-start.html">快速部署</a>。</p></div><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>启用水印</td><td>总开关</td></tr><tr><td>水印类型</td><td><strong>文字</strong>（须 .ttf 字体 URL）或 <strong>图片</strong></td></tr><tr><td>视频封面也打水印</td><td>封面图叠加</td></tr><tr><td>视频文件打水印</td><td>整段视频（仅图片水印；需 ffmpeg）</td></tr></tbody></table><p><strong>文字水印额外字段：</strong> 文案、字号、颜色、描边、<strong>字体文件 URL</strong>（必须 <code>.ttf</code> 公网可访问）</p><p><strong>图片水印额外字段：</strong> 水印图 URL、相对宽度（0～1）</p><p><strong>位置：</strong> 左上/右上/居中/左下/右下 + 透明度 + 边距 X/Y</p><hr><h2 id="tab-system-info" tabindex="-1">Tab 12：系统信息 <a class="header-anchor" href="#tab-system-info" aria-label="Permalink to &quot;Tab 12：系统信息 {#tab-system-info}&quot;">​</a></h2><p><strong>只读：</strong> 应用版本、数据库版本、迁移状态、配置 ID、最后更新时间等。</p><p><strong>可操作：</strong></p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th><th>注意</th></tr></thead><tbody><tr><td>全局违禁词</td><td>跳转违禁词管理</td><td>敏感词拦截策略</td></tr><tr><td>清除缓存</td><td>清客户端相关缓存策略</td><td>不是清服务器所有缓存</td></tr><tr><td>恢复默认设置</td><td><strong>重置全部系统配置</strong></td><td>生产环境慎用，不可撤销</td></tr></tbody></table><hr><h2 id="保存与验证" tabindex="-1">保存与验证 <a class="header-anchor" href="#保存与验证" aria-label="Permalink to &quot;保存与验证&quot;">​</a></h2><ol><li>每个 Tab 改完后点该 Tab 或页面底部 <strong>保存</strong>（以实际 UI 为准）</li><li>有 <strong>测试/获取 Token</strong> 的 Tab 必须点测试通过</li><li>客户端验证：对应功能走一遍（登录、上传、支付、地图）</li><li>失败时查 <strong>系统监控 → 系统状态</strong> 与服务器日志</li></ol><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/site-info">网站信息</a></li><li><a href="/config/region">区域管理</a></li><li><a href="/config/user-rules">用户规则</a></li><li><a href="/features/wechat">微信功能开启</a></li><li><a href="/ops/faq">常见问题</a></li></ul>',93))])}const x=e(b,[["render",p]]);export{k as __pageData,x as default};
